        {
            Console.WriteLine($"Minimum TotalDue {order.Field<decimal>("TotalDue")} for SalesOrderID {order.Field<Int32>("SalesOrderID")}: ");
        }
        Console.WriteLine("");
    }
    //</SnippetMinElements_MQ>
}

