        {
            Name = "Text"
        };

        public WriteFillerText()
        {
            this.Implementation = () => new Sequence
            {
                Variables =
                {
                    text
                },
                Activities =
                {
                    new InvokeFunc<int, string>
                    {
                        Func = GetText,
                        Argument = new InArgument<int>((env) => Quantity.Get(env)),
                        Result = new OutArgument<string>(text)
                    },
