    //<snippet2>
    public class CallbackHandler : ICalculatorDuplexCallback
    {
        public void Equals(double result)
        {
            Console.WriteLine($"Equals({result})");
        }

        public void Equation(string eqn)
        {
            Console.WriteLine($"Equation({eqn})");
        }
