        //a given email is valid.
        private static bool IsValidEmailAddress(string emailAddress)
        {
            string[] splitEmail = emailAddress.Split('@');
            if (splitEmail.Length != 2) return false;
            if (!splitEmail[1].Contains(".")) return false;
            return true;
        }
