                if (obj is Inventory)
                {
                    InventorySurrogated isur = new InventorySurrogated();
                    isur.numpaper = ((Inventory)obj).paper;
                    isur.numpencils = ((Inventory)obj).pencils;
                    isur.pens = ((Inventory)obj).pens;
                    return isur;
                }
                return obj;
