        {
            Console.WriteLine($"Attached to new IContextChannel {owner.GetHashCode()}.");
            this._channel = owner;
        }

        public void Detach(IContextChannel owner)
        {
            Console.WriteLine($"Detached from IContextChannel {owner.GetHashCode()}.");
        }

        #endregion
    }

